-- Seed: Minnesota Multiphasic Personality Inventory, 566-item Form R
-- Patient-facing copy is deliberately neutral. Scoring remains server-side.
-- Item wording source: SelfTestAtlas Arabic item bank (public, unofficial), version 139.
-- Key source: the same item bank's per-option scale tokens, so item numbers and keys align.
-- K-correction and approximate T norms: public 1982 Form R tables; report as provisional.
do $$
declare
  v_id uuid;
begin
  insert into public.assessments (
    slug, title_ar, title_en, patient_label_ar, patient_label_en, category, suite,
    description_ar, description_en, instructions_ar, instructions_en,
    version, active, sort_order, cutoffs, critical_rules, scale_meta
  ) values (
    'mmpi-566',
    'اختبار الشخصية المتعدد الأوجه (MMPI)',
    'Minnesota Multiphasic Personality Inventory (MMPI)',
    'استبيان سمات الشخصية',
    'Personality inventory',
    'clinical', 'clinical',
    'استبيان طويل من 566 عبارة لتكوين صورة وصفية عن سمات الشخصية وطريقة الاستجابة. لا توجد إجابات صحيحة أو خاطئة.',
    'A 566-statement inventory for a descriptive picture of personality and response style. There are no right or wrong answers.',
    ' اقرأ كل عبارة واختر: صحيح، أو خطأ، أو لا أستطيع الإجابة. حاول أن تكون إجابتك الأولى هي الأقرب لشعورك المعتاد.',
    'For each statement choose True, False, or Cannot answer. Use your first reaction as the closest answer.',
    '1.0', true, 40,
    '[{"key": "within", "min": 0, "max": 566, "ar": "ضمن المدى المعتاد", "en": "Within expected range", "descAr": "لم تتجاوز المقاييس السريرية الرئيسية العتبة المعتمدة في الجدول التقريبي. تُراجع الدرجات التفصيلية ومقاييس الصدق داخل التقرير.", "descEn": "No main clinical scale exceeded the threshold on the approximate table. Review the detailed scales and validity indices in the report.", "tone": "emerald"}]'::jsonb,
    '[]'::jsonb,
    '[{"key":"L","ar":"الكذب","en":"Lie","gender":"M","mean":5.7,"sd":2.52,"group":"validity","diagnosisLabel":"وصف الذات بصورة إيجابية على نحو غير معتاد","overviewAr":"يشير إلى نمط من الإجابات يقدّم فيه الشخص نفسه بصورة إيجابية على نحو غير معتاد. ويُراجع إلى جانب المؤشرات الأخرى لصلاحية الاستجابات.","bands":[{"min":50,"max":null,"ar":"يصف الشخص نفسه في الإجابات بصورة إيجابية على نحو غير معتاد. راجع الظروف ومؤشرات الصلاحية الأخرى قبل تفسير سبب ذلك.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"يتضمن النمط عدداً أقل من الإجابات التي يصف فيها الشخص نفسه بصورة إيجابية على نحو غير معتاد. راجعه إلى جانب مؤشرات الصلاحية الأخرى.","rangeLabel":"درجة منخفضة"}]},{"key":"F","ar":"التزييف","en":"Validity","gender":"M","mean":13.68,"sd":6.86,"group":"validity","diagnosisLabel":"الاستجابات غير الشائعة","overviewAr":"يرصد الإجابات النادرة في المجموعة المرجعية. ويُفهم نمطها في ضوء الظروف، بما في ذلك الضيق الذي يذكره الشخص وطريقة فهمه للأسئلة.","bands":[{"min":null,"max":55,"ar":"تتضمن الإجابات عدداً أقل من الاستجابات النادرة مقارنة بالمجموعة المرجعية. راجع مؤشرات الصلاحية الأخرى أيضاً.","rangeLabel":"T < 56"},{"min":56,"max":70,"ar":"كانت بعض الإجابات قليلة الشيوع في المجموعة المرجعية. وقد يساعد الضغط الذي تعرض له الشخص مؤخراً وطريقة فهمه للأسئلة على تفسير هذا النمط.","rangeLabel":"56–70"},{"min":71,"max":80,"ar":"يخرج عدد أكبر من الإجابات عن النمط الشائع في المجموعة المرجعية. راجع الإجابات مجتمعة وظروف التقييم.","rangeLabel":"70–80"},{"min":81,"max":90,"ar":"يستدعي عدد الإجابات النادرة مراجعة أدق لصلاحية الاستجابات قبل تفسير المقاييس الأخرى.","rangeLabel":"80–90"},{"min":91,"max":null,"ar":"نمط الإجابات غير معتاد بدرجة كبيرة في المجموعة المرجعية. راجع ظروف التقييم وفهم الأسئلة واتساق الإجابات قبل تفسير النتائج.","rangeLabel":"أكثر من 90"}]},{"key":"K","ar":"التصحيح","en":"Correction","gender":"M","mean":13.0,"sd":4.66,"group":"validity","diagnosisLabel":"أسلوب الاستجابة الدفاعي","overviewAr":"يساعد على تفسير الاستجابات التي قد تتسم بالتحفظ.","bands":[{"min":50,"max":null,"ar":"قد تعكس الإجابات تحفظاً في الإفصاح عن الصعوبات. ضع ظروف التقييم ومؤشرات صلاحية الاستجابات الأخرى في الحسبان.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"قد تعكس الإجابات استعداداً أكبر للحديث عن الصعوبات. ضع نمط الإجابات العام والظروف الحالية في الحسبان.","rangeLabel":"درجة منخفضة"}]},{"key":"Hs","ar":"توهم المرض","en":"Hypochondriasis","gender":"M","mean":15.42,"sd":4.79,"correctionKey":"K","correctionWeight":0.5,"group":"clinical","diagnosisLabel":"المخاوف بشأن الصحة الجسدية","overviewAr":"يتناول الانتباه إلى الأعراض الجسدية والقلق بشأن الصحة.","bands":[{"min":71,"max":null,"ar":"أفاد الشخص بأنه يولي الأعراض الجسدية اهتماماً كبيراً أو يقلق بشأن صحته. ضع حالته الصحية وظروفه في الحسبان عند مراجعة هذه الإجابات.","rangeLabel":"أكثر من 70"},{"min":56,"max":70,"ar":"أفاد الشخص ببعض القلق بشأن الصحة الجسدية أو بالانتباه إلى أعراض جسدية.","rangeLabel":"56–70"},{"min":null,"max":55,"ar":"أفاد الشخص بمخاوف أقل من النوع الذي تتناوله الأسئلة حول الصحة الجسدية.","rangeLabel":"درجة منخفضة"}]},{"key":"D","ar":"الاكتئاب","en":"Depression","gender":"M","mean":26.16,"sd":4.97,"group":"clinical","diagnosisLabel":"تجارب مرتبطة بالاكتئاب","overviewAr":"يتناول انخفاض المزاج والإحباط والتجارب المرتبطة بهما التي يذكرها الشخص في الاستبيان.","bands":[{"min":61,"max":null,"ar":"تتضمن الإجابات إشارات أكثر إلى انخفاض المزاج أو الإحباط أو الأفكار الناقدة للذات. راجع التجارب التي أشار إليها الشخص والمدة التي استمرت فيها.","rangeLabel":"T > 60"},{"min":40,"max":60,"ar":"تقع الإجابات ضمن النطاق الأوسط الوارد في التقرير الأصلي. وقد توضح بعض الإجابات كيف يشعر الشخص وكيف ينظر إلى وضعه.","rangeLabel":"40–60"},{"min":null,"max":39,"ar":"أفاد الشخص بتجارب أقل من النوع الذي يتناوله هذا المقياس. ضع أسلوب الإجابة وبقية النتائج في الحسبان.","rangeLabel":"درجة منخفضة"}]},{"key":"Hy","ar":"الهستيريا","en":"Hysteria","gender":"M","mean":22.07,"sd":5.36,"group":"clinical","diagnosisLabel":"الشكاوى الجسدية والاستجابة للضغط","overviewAr":"يتناول الشكاوى الجسدية المذكورة في الاستبيان وأنماط الإجابة المرتبطة بالتعامل مع الضغط.","bands":[{"min":50,"max":null,"ar":"يتضمن النمط شكاوى جسدية أو إجابات متعلقة بالتعامل مع الضغط بدرجة أكبر. ضع طبيعة الصعوبات المذكورة وظروفها في الحسبان.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"أعطى الشخص عدداً أقل من الإجابات المرتبطة بهذا النمط من الشكاوى الجسدية والتعامل مع الضغط.","rangeLabel":"درجة منخفضة"}]},{"key":"Pd","ar":"الانحراف السيكوباثي","en":"Psychopathic deviate","gender":"M","mean":24.38,"sd":4.27,"correctionKey":"K","correctionWeight":0.4,"group":"clinical","diagnosisLabel":"التعارض مع القواعد والتوقعات","overviewAr":"يتناول ما يذكره الشخص من احتكاك مع التوقعات الاجتماعية أو القواعد أو أصحاب السلطة.","bands":[{"min":50,"max":null,"ar":"تتضمن الإجابات إشارات أكثر إلى التعارض مع القواعد أو أصحاب السلطة أو التوقعات الاجتماعية. راجع المواقف المحددة التي وصفها الشخص.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"تتضمن الإجابات إشارات أقل إلى التعارض مع القواعد أو التوقعات الاجتماعية في بنود هذا المقياس.","rangeLabel":"درجة منخفضة"}]},{"key":"Mf","ar":"الذكورة والأنوثة","en":"Masculinity-femininity","gender":"M","mean":27.56,"sd":4.04,"group":"clinical","diagnosisLabel":"الاهتمامات المرتبطة بالأدوار الجندرية","overviewAr":"يتناول الاهتمامات والتفضيلات في ضوء تصورات تاريخية عن الأدوار الجندرية. وتعكس الدرجة التصورات التي بُني عليها هذا الاستبيان.","bands":[{"min":50,"max":null,"ar":"تبتعد الاهتمامات المذكورة بدرجة أكبر عن التوقعات التاريخية بشأن الأدوار الجندرية التي تستخدمها هذه النسخة للمقارنة.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"تقترب الاهتمامات المذكورة بدرجة أكبر من التوقعات التاريخية بشأن الأدوار الجندرية التي تستخدمها هذه النسخة للمقارنة.","rangeLabel":"درجة منخفضة"}]},{"key":"Pa","ar":"البارانويا","en":"Paranoia","gender":"M","mean":12.84,"sd":3.92,"group":"clinical","diagnosisLabel":"عدم الثقة في التعامل مع الآخرين","overviewAr":"يتناول الشك والحساسية لما قد يفعله الآخرون أو لكيفية استجابتهم.","bands":[{"min":76,"max":null,"ar":"تتضمن الإجابات إشارات أكثر إلى عدم الثقة أو الحساسية تجاه تصرفات الآخرين. راجع المواقف الموصوفة والنتائج مجتمعة.","rangeLabel":"أكثر من 75"},{"min":60,"max":75,"ar":"قد يشير الشخص إلى حذر أكبر بشأن نيات الآخرين أو حساسية أكبر للنقد والخلاف.","rangeLabel":"60–75"},{"min":40,"max":59,"ar":"تقع الإجابات ضمن النطاق الأوسط الوارد في التقرير الأصلي. وقد تبيّن الإجابات الفردية المواقف التي يميل فيها الشخص إلى الثقة أو الحذر.","rangeLabel":"40–60"},{"min":null,"max":39,"ar":"أشار الشخص إلى قدر أقل من عدم الثقة في البنود التي يغطيها هذا المقياس.","rangeLabel":"T < 40"}]},{"key":"Pt","ar":"القلق النفسي","en":"Psychasthenia","gender":"M","mean":31.14,"sd":5.71,"correctionKey":"K","correctionWeight":1.0,"group":"clinical","diagnosisLabel":"القلق والضيق المستمران","overviewAr":"يتناول القلق المتكرر والتوتر وصعوبة صرف الانتباه عن الأفكار المؤلمة.","bands":[{"min":61,"max":null,"ar":"تتضمن الإجابات إشارات أكثر إلى تكرر القلق أو التوتر أو صعوبة صرف الانتباه عن الأفكار المزعجة.","rangeLabel":"T > 60"},{"min":40,"max":60,"ar":"تقع الإجابات ضمن النطاق الأوسط الوارد في التقرير الأصلي. راجع المخاوف المحددة في ضوء المتطلبات الحالية.","rangeLabel":"40–60"},{"min":null,"max":39,"ar":"أشار الشخص إلى تجارب أقل تتعلق بالقلق المستمر أو التوتر مما يتناوله هذا المقياس.","rangeLabel":"T < 40"}]},{"key":"Sc","ar":"الفصام","en":"Schizophrenia","gender":"M","mean":36.47,"sd":8.24,"correctionKey":"K","correctionWeight":1.0,"group":"clinical","diagnosisLabel":"تجارب غير مألوفة وشعور بالعزلة الاجتماعية","overviewAr":"يتناول المدركات أو الأفكار غير المألوفة والشعور بالعزلة أو الانفصال عن الآخرين.","bands":[{"min":50,"max":null,"ar":"أشار الشخص إلى تجارب أكثر تتعلق بأفكار أو مدركات غير معتادة أو بشعور بالانفصال عن الآخرين. راجع مؤشرات الصلاحية والظروف التي حدثت فيها هذه التجارب.","rangeLabel":"درجة مرتفعة"},{"min":null,"max":49,"ar":"أشار الشخص إلى تجارب أقل من النوع الذي يتناوله هذا المقياس.","rangeLabel":"درجة منخفضة"}]},{"key":"Ma","ar":"الهوس الخفيف","en":"Hypomania","gender":"M","mean":21.22,"sd":4.88,"correctionKey":"K","correctionWeig